# C 语言模拟 Windows 线程切换

本篇用一份极简的 C 代码，剥离 TCB、调度队列、状态机等一切外围概念，**只聚焦线程切换的物理本质——伪造堆栈 + 交换 ESP。**

### 核心思想

1. 只有两个"线程"做乒乓式交替切换，不需要任何调度器。其中一个是系统本身的主线程，另一个是我们额外添加的，用一片全局数组充当其私有堆栈。
2. 线程切换函数分两层：第一层负责 `pushad`/`pushfd` 保存现场；第二层是核心逻辑，只做一件事——**交换 ESP**。
3. 在数组中预先构造好第二个线程的堆栈调用链，让 CPU 切过去时以为它"刚好在第二层被挂起"，能沿着伪造的调用链一路返回到工作函数。

### 两层切换函数

切换函数拆成两层，各司其职：

**第一层：保护/恢复现场**

```c
void __declspec(naked) switch_layer1() {
    __asm {
        pushfd          // 保存标志寄存器
        pushad          // 保存 8 个通用寄存器
        call switch_layer2   // 调用第二层，执行 ESP 交换
        popad           // 切回来后恢复寄存器
        popfd
        ret             // 返回到调用点
    }
}
```

**第二层：交换 ESP（核心）**

```c
void __declspec(naked) switch_layer2() {
    __asm {
        mov esp_save, esp       // 1. 保存当前线程的 ESP
        mov eax, esp_restore    // 2. 取出目标线程的 ESP
        mov esp, eax            //    覆盖物理 ESP（此刻已跳到另一片内存）

        // 3. 互换 esp_save 与 esp_restore，为下一次切换做准备
        mov ecx, esp_save
        mov esp_save, eax
        mov esp_restore, ecx

        ret                     // 从目标线程的栈顶弹出返回地址，跳过去执行
    }
}
```

> [!important] 线程切换的物理本质
> 所谓"线程切换"，就是**更换 CPU 的 ESP 寄存器**。ESP 一换，栈上的返回地址、寄存器快照全都变了，CPU 的执行流自然就迁移到了另一个"线程"。

### 在数组中构造堆栈调用链

第二个线程从未被 CPU 执行过，没有真实的调用历史。所以我们必须在数组中**伪造一套完整的堆栈快照**，让它看起来就像"刚好在 `switch_layer2` 内部被挂起"一样。

堆栈调用链的目标是：**当前执行位置是第二层，上一个调用链是第一层，再上一个调用链是工作函数。**

用一个结构体精确描述栈中每个位置存放的内容：

```c
struct ThreadContext {
    // ---- [低地址，当前栈顶 ESP] ----
    unsigned int layer1_resume_eip;  // switch_layer2 的 ret 弹出此值 → 跳到第一层的 popad 处
    unsigned int edi;                // pushad 保存的 8 个通用寄存器
    unsigned int esi;
    unsigned int ebp;
    unsigned int esp_dummy;
    unsigned int ebx;
    unsigned int edx;
    unsigned int ecx;
    unsigned int eax;
    unsigned int eflags;             // pushfd 保存的标志寄存器
    unsigned int worker_func_eip;    // 第一层的 ret 弹出此值 → 跳到工作函数
    unsigned int dummy_ret;          // 工作函数的伪造返回地址（占位）
    // ---- [高地址，栈底] ----
};
```

然后将结构体直接映射到数组尾部，填入初始值：

```c
#define STACK_SIZE 16384
unsigned char thread_stack[STACK_SIZE];

// 将结构体指针对准数组尾部（栈底）
ThreadContext* ctx = (ThreadContext*)(thread_stack + STACK_SIZE - sizeof(ThreadContext));

ctx->layer1_resume_eip = <第一层 popad 指令的地址>;  // 第二层 ret 后跳到这里
ctx->edi = ctx->esi = ctx->ebp = ... = 0;            // 寄存器初始值全部置零
ctx->eflags = 0x202;                                  // 开启中断标志
ctx->worker_func_eip = (unsigned int)worker_func;     // 第一层 ret 后跳到工作函数
ctx->dummy_ret = 0;                                   // 占位

// 将数组中构造好的栈顶地址赋给 esp_restore，等待第一次切换
esp_restore = (unsigned int)ctx;
```

构造完毕后，`thread_stack` 数组的内存布局如下（从低地址到高地址）：

```
         thread_stack 数组
  ┌─────────────────────────────────┐ ← thread_stack[0]（低地址）
  │          （未使用空间）           │
  │              ...                │
  ├─────────────────────────────────┤ ← ctx / esp_restore 指向此处
  │  layer1_resume_eip  ──→ popad  │ ◄ switch_layer2 的 ret 弹出
  │  EDI = 0                       │
  │  ESI = 0                       │
  │  EBP = 0                       │
  │  ESP = 0  (占位)               │  ◄ pushad 保存的 8 个寄存器
  │  EBX = 0                       │
  │  EDX = 0                       │
  │  ECX = 0                       │
  │  EAX = 0                       │
  │  EFLAGS = 0x202                │ ◄ pushfd 保存的标志寄存器
  │  worker_func_eip ──→ worker    │ ◄ switch_layer1 的 ret 弹出
  │  dummy_ret = 0                 │ ◄ 工作函数的伪造返回地址
  └─────────────────────────────────┘ ← thread_stack[STACK_SIZE]（高地址 / 栈底）
```

### 切换执行流程

当主线程第一次调用 `switch_layer1()` 时，整个切换链条如下：

```
主线程调用 switch_layer1()
  ├─ pushfd, pushad            → 主线程寄存器压入【主线程自己的栈】
  ├─ call switch_layer2
  │    ├─ 保存主线程 ESP 到 esp_save
  │    ├─ 将 esp_restore 加载到 ESP   ← 此刻 ESP 指向 thread_stack 数组！
  │    └─ ret                  → 弹出 layer1_resume_eip → 跳到第一层的 popad
  ├─ popad                     → 从数组中弹出伪造的 8 个寄存器
  ├─ popfd                     → 从数组中弹出伪造的 EFLAGS
  └─ ret                       → 弹出 worker_func_eip → 跳到 worker_func() 开始执行！
```

工作函数内部再次调用 `switch_layer1()` 时，就是真实的现场保存了——把工作线程的寄存器压入 `thread_stack`，然后切回主线程的栈，两个线程从此交替运行。

### 完整代码

```cpp
#include <stdio.h>
#include <windows.h>

// ============================================================================
// 全局数据
// ============================================================================

#define STACK_SIZE  16384                    // 第二个线程的堆栈大小 (16KB)
unsigned char  thread_stack[STACK_SIZE];     // 第二个线程的堆栈数组
unsigned int   esp_save = 0;             // 切换时保存当前线程的 ESP
unsigned int   esp_restore = 0;             // 切换时恢复目标线程的 ESP

// ============================================================================
// 堆栈调用链结构体
// 与 switch_layer1 中 pushfd / pushad 的压栈顺序严格对应，
// 用来在 thread_stack 数组中精准构造第二个线程的初始调用链。
// ============================================================================

struct ThreadContext {
	// ---- 低地址 (栈顶, ESP 指向此处) ----
	unsigned int layer1_resume_eip;     // switch_layer2 ret → 跳到第一层 popad 处
	unsigned int edi;                   // ┐
	unsigned int esi;                   // │
	unsigned int ebp;                   // │
	unsigned int esp_dummy;             // ├─ pushad 压入的 8 个通用寄存器
	unsigned int ebx;                   // │
	unsigned int edx;                   // │
	unsigned int ecx;                   // │
	unsigned int eax;                   // ┘
	unsigned int eflags;                // pushfd 压入的标志寄存器
	unsigned int worker_func_eip;       // switch_layer1 ret → 跳到工作函数
	unsigned int dummy_ret;             // 工作函数的伪造返回地址 (占位)
	// ---- 高地址 (栈底) ----
};

// ============================================================================
// 第二层 (核心)：交换 ESP
// ============================================================================

void __declspec(naked) switch_layer2() {
	__asm {
		mov esp_save, esp           // 保存当前线程 ESP
		mov eax, esp_restore        // 取出目标线程 ESP
		mov esp, eax                // 切换到目标线程的栈

		mov ecx, esp_save           // 互换 esp_save 与 esp_restore，
		mov esp_save, eax           // 为下一次反向切换做准备
		mov esp_restore, ecx

		ret
	}
}

// ============================================================================
// 第一层：保存/恢复寄存器现场，调用第二层
// ============================================================================

void __declspec(naked) switch_layer1() {
	__asm {
		pushfd
		pushad
		call switch_layer2          // 进入第二层执行 ESP 交换
		popad                       // 切回来后从这里继续，恢复现场
		popfd
		ret
	}
}

// ============================================================================
// 工作函数 (第二个线程的业务逻辑)
// ============================================================================

void worker_func() {
	int count = 0;
	while (1) {
		printf("[Worker Thread] is running... count = %d\n", ++count);
		Sleep(500);
		switch_layer1();            // 切换回主线程
	}
}

// ============================================================================
// 主函数
// ============================================================================

int main() {
	printf("[Main Thread] initializing thread stack...\n");

	// --- 在数组中构造第二个线程的堆栈调用链 ---
	ThreadContext* ctx = (ThreadContext*)(thread_stack + STACK_SIZE - sizeof(ThreadContext));

	// 计算第一层 call switch_layer2 之后 popad 指令的地址
	unsigned char* p = (unsigned char*)switch_layer1;
	if (*p == 0xE9)                 // 处理 Debug 模式 MSVC 的 JMP Thunk
		p += 5 + *(int*)(p + 1);
	p += 7;                         // pushfd(1) + pushad(1) + call(5) = 7 字节偏移

	ctx->layer1_resume_eip = (unsigned int)p;               // switch_layer2 ret 后跳到 popad
	ctx->edi = 0;
	ctx->esi = 0;
	ctx->ebp = 0;
	ctx->esp_dummy = 0;
	ctx->ebx = 0;
	ctx->edx = 0;
	ctx->ecx = 0;
	ctx->eax = 0;
	ctx->eflags = 0x00000202;                           // IF 中断标志位置位
	ctx->worker_func_eip = (unsigned int)worker_func;       // switch_layer1 ret 后跳到工作函数
	ctx->dummy_ret = 0;

	esp_restore = (unsigned int)ctx;

	// --- 主线程运行循环，与工作线程交替执行 ---
	int main_count = 0;
	while (main_count < 5) {
		printf("[Main Thread] is running... count = %d\n", ++main_count);
		Sleep(500);
		switch_layer1();            // 切换到工作线程
	}

	printf("[Main Thread] execution finished.\n");
	return 0;
}

```

